Matrix features = Matrix.fromRows(new double[][] {
    {1.0, 2.0}, {2.0, 1.0}, {3.0, 4.0}, {4.0, 3.0}, {5.0, 6.0}
});
KernelPCA kpca = KernelPCA.builder()
        .components(2)
        .rbf(0.5)
        .build()
        .fit(features);
Matrix projected = kpca.transform(features);
double[] eigenvalues = kpca.eigenvalues();

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {1, 0}, {0, 1}, {1, 1}});
double[] y = {0.0, 1.0, 1.0, 2.0};
KernelRidge model = KernelRidge.builder()
        .rbf(1.0)
        .alpha(0.1)
        .build()
        .fit(x, y);
double[] predictions = model.predict(x);
double[] dual = model.dualCoef();

LabelEncoder encoder = new LabelEncoder();
double[] codes = encoder.fitTransform(new double[]{3.0, 1.0, 3.0, 2.0});
double[] original = encoder.inverseTransform(codes);
double[] classes = encoder.classes();

LabelEncoder names = new LabelEncoder();
int[] ids = names.fitTransform(new String[]{"cat", "dog", "cat"});
String[] restored = names.inverseTransformStrings(ids);

Matrix x = Matrix.fromRows(new double[][]{{1, 0}, {0, 1}, {1, 1}, {2, 2}});
double[] y = {1.0, 2.0, 3.0, 5.0};
Lasso lasso = Lasso.builder()
        .alpha(0.1)
        .maxIterations(500)
        .build()
        .fit(x, y);
double[] coefficients = lasso.weights();
double bias = lasso.intercept();

Matrix train = Matrix.fromRows(new double[][]{{0, 0}, {1, 0}, {0, 1}, {1, 1}});
double[] y = {0, 0, 1, 1};
LogisticRegression model = LogisticRegression.builder().build().fit(train, y);
LimeExplainer lime = new LimeExplainer(model, train, 200, 0.75, 7L);
LimeExplainer.LocalExplanation explanation = lime.explainInstance(new double[]{1.0, 0.2});
double[] weights = explanation.featureWeights();
double fidelity = explanation.r2Fidelity();
int[] ranked = explanation.topFeatures();

Matrix x = Matrix.fromRows(new double[][]{{0, 1}, {1, 1}, {2, 1}, {3, 1}});
double[] y = {1.0, 3.0, 5.0, 7.0};
LinearRegression model = LinearRegression.builder()
        .learningRate(0.05)
        .epochs(2000)
        .fitIntercept(true)
        .build()
        .fit(x, y);
double[] predictions = model.predict(x);
double one = model.predictOne(new double[]{4.0, 1.0}, 0);

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}});
double[] y = {0, 0, 1, 1};
LinearSVM svm = LinearSVM.builder()
        .lambda(0.01)
        .epochs(20)
        .seed(42L)
        .build()
        .fit(x, y);
double[] labels = svm.predict(x);
double[] w = svm.weights();
double b = svm.bias();

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}});
double[] y = {0, 0, 1, 1};
LogisticRegression model = LogisticRegression.builder()
        .learningRate(0.1)
        .epochs(2000)
        .build()
        .fit(x, y);
double[] probability = model.predictProbability(x);
double[] labels = model.predict(x);

double[] expected = {1, 0, 1, 1, 0};
double[] predicted = {1, 0, 0, 1, 0};
double accuracy = Metrics.accuracy(expected, predicted);
double f1 = Metrics.f1(expected, predicted, 1.0);
int[][] matrix = Metrics.confusionMatrix(expected, predicted);
double auc = Metrics.rocAuc(expected, new double[]{0.9, 0.1, 0.4, 0.8, 0.2});

Matrix x = Matrix.fromRows(new double[][]{{1, 10}, {2, 20}, {3, 30}});
MinMaxScaler scaler = MinMaxScaler.builder()
        .featureRange(-1.0, 1.0)
        .clip(true)
        .build()
        .fit(x);
Matrix scaled = scaler.transform(x);
Matrix restored = scaler.inverseTransform(scaled);
double[] scale = scaler.scale();

Matrix x = Matrix.fromRows(new double[][]{
    {0, 1.5}, {1, 2.5}, {2, 3.5}
});
OneHotEncoder encoder = OneHotEncoder.builder()
        .categoricalColumns(0)
        .handleUnknown(OneHotEncoder.HandleUnknown.IGNORE)
        .build()
        .fit(x);
Matrix encoded = encoder.transform(x);
int width = encoder.outputFeatureCount();
Matrix back = encoder.inverseTransform(encoded);

Matrix features = Matrix.fromRows(new double[][] {
    {2.5, 2.4}, {0.5, 0.7}, {2.2, 2.9},
    {1.9, 2.2}, {3.1, 3.0}, {2.3, 2.7}
});
PCA pca = PCA.builder()
        .components(1)
        .solver(EigenSolver.AUTO)
        .whiten(true)
        .build()
        .fit(features);
Matrix projected = pca.transform(features);
Matrix restored = pca.inverseTransform(projected);
double[] ratio = pca.explainedVarianceRatio();
